def compareLibrariesBookshops(libraries:list,bookshops:list):
    libraryBooks = set()
    for lib in libraries:
        libraryBooks.update(lib)

    bookshopBooks = set()
    for shop in bookshops:
        bookshopBooks.update(shop)

    commonBooks = libraryBooks.intersection(bookshopBooks)
    uniqueLibraryBooks = libraryBooks.difference(bookshopBooks)
    uniqueBookshopBooks = bookshopBooks.difference(libraryBooks)

    return len(commonBooks),len(uniqueLibraryBooks),len(uniqueBookshopBooks)

